// Scalar complex arithmetic on [re, im] pairs.
// Used by the expression interpreter (constant folding, hoisted-array precomputation)
// and by tests. The hot loops never call these: they use code generated by expr.js
// that inlines the same formulas on plain doubles.

export const C = (re, im = 0) => [re, im];

export const add = (a, b) => [a[0] + b[0], a[1] + b[1]];
export const sub = (a, b) => [a[0] - b[0], a[1] - b[1]];
export const neg = (a) => [-a[0], -a[1]];
export const mul = (a, b) => [a[0] * b[0] - a[1] * b[1], a[0] * b[1] + a[1] * b[0]];
export function div(a, b) {
  const d = b[0] * b[0] + b[1] * b[1];
  return [(a[0] * b[0] + a[1] * b[1]) / d, (a[1] * b[0] - a[0] * b[1]) / d];
}
export const abs = (a) => Math.hypot(a[0], a[1]);
export const conj = (a) => [a[0], -a[1]];
export function exp(a) {
  const e = Math.exp(a[0]);
  return [e * Math.cos(a[1]), e * Math.sin(a[1])];
}
export const log = (a) => [0.5 * Math.log(a[0] * a[0] + a[1] * a[1]), Math.atan2(a[1], a[0])];
export function sqrt(a) {
  const m = Math.hypot(a[0], a[1]);
  const r = Math.sqrt(Math.max(0, (m + a[0]) / 2));
  const i = Math.sqrt(Math.max(0, (m - a[0]) / 2));
  return [r, a[1] < 0 ? -i : i];
}
export function pow(a, b) {
  if (b[1] === 0 && Number.isInteger(b[0]) && Math.abs(b[0]) <= 64) {
    let n = Math.abs(b[0]);
    let r = [1, 0];
    let base = a;
    while (n > 0) {
      if (n & 1) r = mul(r, base);
      base = mul(base, base);
      n >>= 1;
    }
    return b[0] < 0 ? div([1, 0], r) : r;
  }
  if (a[0] === 0 && a[1] === 0) return [0, 0];
  return exp(mul(b, log(a)));
}
export const sin = (a) => [Math.sin(a[0]) * Math.cosh(a[1]), Math.cos(a[0]) * Math.sinh(a[1])];
export const cos = (a) => [Math.cos(a[0]) * Math.cosh(a[1]), -Math.sin(a[0]) * Math.sinh(a[1])];
export function tan(a) {
  const d = Math.cos(2 * a[0]) + Math.cosh(2 * a[1]);
  return [Math.sin(2 * a[0]) / d, Math.sinh(2 * a[1]) / d];
}
export const sinh = (a) => [Math.sinh(a[0]) * Math.cos(a[1]), Math.cosh(a[0]) * Math.sin(a[1])];
export const cosh = (a) => [Math.cosh(a[0]) * Math.cos(a[1]), Math.sinh(a[0]) * Math.sin(a[1])];
export function tanh(a) {
  const d = Math.cosh(2 * a[0]) + Math.cos(2 * a[1]);
  return [Math.sinh(2 * a[0]) / d, Math.sin(2 * a[1]) / d];
}
export const cis = (a) => exp([-a[1], a[0]]);

/**
 * Eccentric anomaly: the solution E of Kepler's equation E - e sin E = M (complex
 * Newton, Danby's starting value). For real 0 <= e < 1 it is real, increasing in M,
 * and E(M + 2pi) = E(M) + 2pi.
 */
export function kepler(e, M) {
  let Er = M[0] + 0.85 * e[0] * (Math.sin(M[0]) < 0 ? -1 : 1), Ei = M[1];
  for (let it = 0; it < 80; it++) {
    const s = sin([Er, Ei]), c = cos([Er, Ei]);
    const es = mul(e, s), ec = mul(e, c);
    const gr = Er - es[0] - M[0], gi = Ei - es[1] - M[1];
    const [dr, di] = div([gr, gi], [1 - ec[0], -ec[1]]);
    Er -= dr; Ei -= di;
    if (dr * dr + di * di < 1e-30 * (1 + Er * Er + Ei * Ei)) break;
  }
  return [Er, Ei];
}

export function fmt(z, digits = 6) {
  const [re, im] = z;
  const r = Number(re.toPrecision(digits));
  const i = Number(Math.abs(im).toPrecision(digits));
  if (im === 0) return `${r}`;
  return `${r} ${im < 0 ? '−' : '+'} ${i}i`;
}
